#!/usr/bin/env python3
# luxarch:delete-proposal-evidence hook v4 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Refuse a request to delete something unless each candidate says what it is and, for code, why it is dead.

FLEET-AGENT-CONDUCT-STANDARD #6 and `luxarch --playbook dead-code` ("A candidate is a QUESTION")
already say it: zero references answers "is this called?", not "should this exist?". Unreferenced
code is SUPERSEDED (a live successor does its job), NEVER-WIRED (what should call it was never
built, so deleting it buries the defect) or ORPHANED, and the proposal has to say which, with
evidence that can be checked. Agents kept asking "each has zero references, delete them all?",
because the only hook was on `rm` and nothing looked at the ASK.

**AskUserQuestion is the gate.** It is structured and it blocks before the owner sees anything. A
question whose text, header, or any option's label or description proposes a removal ("Delete
them?", "OK to drop", "Remove all 5", "I'd delete them", "can it go?", "should be deleted", "fold X
into Y", "git rm x.py", and the retroactive "keep it removed") must carry one block per candidate,
in the format the dead-code playbook defines (a test keeps the copy below identical to it):
  * repo code: `what:` path:line + symbol, `class:`, `refs:` with its count and `lanes:`, and per
    class `successor:` + `live:` (path:line each), `missing caller:` (plus an option whose label
    starts with Wire/Build/Implement), or `why no successor:`;
  * anything else: `what: not-code: <kind> <name>`, kind one of branch, tag, image, volume,
    container, stack, external, data, doc. That is an honest declaration and needs nothing more,
    but it is refused when any token of the name is a tracked path or a symbol the repo defines;
  * a question about how a delete FEATURE behaves (refuse or cascade, retention, who may):
    `what: not-code: behaviour <feature>` (v4). It removes no code, so it may name the feature's
    own code, and a name the question mentions needs no block, UNLESS it sits in a sentence that
    proposes a removal: that name still needs the full code block. Name the feature's code in a
    sentence of its own. "Should we delete its articles too? `delete_section` walks them." passes;
    "Delete `delete_section` too?" does not.

**What is checked against the session's checkout**, because a hook can check it soundly. That is the
working tree the event's cwd is in when it shares $CLAUDE_PROJECT_DIR's git directory (an issue
worktree, where a successor was just written), else $CLAUDE_PROJECT_DIR itself (v2):
every path resolves inside the checkout and is that long; the `what:` symbol is on or near its line
(word boundary); the successor is not the candidate, and its line (or one within 5) is the `def` or
`class` of a symbol, or it is another tracked file; the `live:` line is code that names that
symbol (a route handler's route `name=`, a successor file's stem), and is not the candidate; a
whole-file candidate is its tracked path, its symbol the file's stem (v3);
the `refs:` count equals `git grep -cw <symbol>`. Repo code the question names with no block of its
own is listed. **What cannot be checked**, and stays the author's word: that the successor does the
candidate's job, and that the lanes were actually searched.

**Stop is a best-effort reminder, not a gate.** Prose cannot be judged reliably, so on Stop the hook
fires once (`stop_hook_active`) and only when the last paragraph of the final message asks to remove
something, names a tracked file or a repo-defined symbol, and carries no block that passes the same
checks. It reads the last 4 KB of the final transcript entry and never an earlier turn. Ask removal
questions with AskUserQuestion. "Proceed with the plan above?" names no removal and is not caught.

Every pattern is bounded, so a 256 KB message is judged in linear time. Fails OPEN on unreadable
input and, for the whole question, on a checkout it cannot read (CLAUDE_PROJECT_DIR unset or not a
git checkout): a hook that blocks on its own uncertainty gets switched off.
"""

from __future__ import annotations

import ast
import io
import json
import os
import re
import subprocess
import sys
import tokenize
from pathlib import Path

ASK_TOOL = "AskUserQuestion"
# bound to a name: an inline `except (A, B)` formats differently under py314 (PEP 758)
_GIT_ERRORS = (OSError, subprocess.SubprocessError)
_PATH_ERRORS = (ValueError, OSError)
_PARSE_ERRORS = (SyntaxError, ValueError)
_READ_ERRORS = (SyntaxError, ValueError, tokenize.TokenError)

# The proposal format, byte-identical to the fenced blocks in docs/playbooks/dead-code.md.
TEMPLATE = """\
what: app/services/core/email_core_service.py:42  EmailCoreService.mark_bounced
class: superseded | never-wired | orphaned   (exactly one)
refs: `git grep -cw mark_bounced` -> 1 (its own def); lanes: getattr/registry, template/JS strings, serializers -> none
successor: app/services/core/bounce_core_service.py:88  BounceCoreService.record    (superseded)
live: app/routers/webhooks_router.py:31  the route that calls record()             (superseded)
missing caller: the Mailgun bounce webhook route that should call it               (never-wired)
why no successor: `grep -rIni 'bounce\\|suppress' app/` -> no other writer            (orphaned)"""
NOT_CODE = "what: not-code: branch feature/old-auth"
KINDS = (
    "branch",
    "tag",
    "image",
    "volume",
    "container",
    "stack",
    "external",
    "data",
    "doc",
    "behaviour",
)

_MAX_TEXT = 262144  # judge at most 256 KB of one question
_STOP_TAIL = 4096
_NEAR = 5  # lines either side of a cited line that still count as "at" it

# ── Is this a proposal to remove something? ─────────────────────────────────────────────────────
_VERB = (
    r"(?:delete|remove|drop|retire|prune|purge|nuke|wipe|excise|strip(?:[ \t]{1,3}out)?|kill|trash"
    r"|scrap|toss|ditch|eliminate|erase|bin|axe|chop|sunset"
    r"|rip[ \t]{1,3}out|get[ \t]{1,3}rid[ \t]{1,3}of|clean[ \t]{1,3}up)"
)
_GERUND = (
    r"(?:deleting|removing|dropping|retiring|pruning|purging|nuking|stripping|killing|trashing"
    r"|scrapping|tossing|ditching|eliminating|erasing|binning|axing|sunsetting|ripping[ \t]{1,3}out"
    r"|cleaning[ \t]{0,3}up|getting[ \t]{1,3}rid[ \t]{1,3}of)"
)
_PARTICIPLE = (
    r"(?:deleted|removed|dropped|retired|pruned|purged|nuked|wiped|stripped|killed|trashed|scrapped"
    r"|tossed|ditched|eliminated|erased|binned|axed|sunset(?:ted)?)"
)
_NOUN = r"(?:deletion|removal|retirement)"
_PRONOUN = r"(?:it|them|these|those|this|all|both|each|everything)"
_SEP = r"[.?!;:,+&—–]"  # sentence and clause breaks, em and en dashes included
_PROPOSAL = (
    # sentence-, line-, label- or spaced-dash-initial (v4: "x() - delete?") imperative, noun or gerund:
    # "Delete them?", "Removal OK?",
    # "— remove?", "Removing X is safe?"
    re.compile(
        rf"(?im)(?:^|{_SEP}[ \t]{{0,5}}|[ \t]-[ \t]{{1,5}}|\n)[ \t]{{0,5}}(?:just[ \t]{{1,3}}|also[ \t]{{1,3}})?(?:{_VERB}\b"
        # a noun only as a request ("Removal OK?", "Deletion of X", a bare "Deletion" label), not a
        # title ("Deletion line"); a gerund only in a sentence that asks ("Removing X is safe?")
        rf"|{_NOUN}(?:[ \t]{{1,3}}(?:of|ok|okay|approved)\b|[ \t]{{0,3}}\?|[ \t]{{0,3}}$)"
        rf"|{_GERUND}\b[^.?!\n]{{0,160}}\?)"
    ),
    # the agent as subject: "I'd delete them", "I will remove", "we drop", "I recommend we delete"
    re.compile(
        rf"(?i)\b(?:I|we)(?:'ll|'d|[ \t]{{1,3}}(?:will|would|can|could|should|shall|may|might|want[ \t]to"
        rf"|plan[ \t]to|propose[ \t]to|need[ \t]to|intend[ \t]to))?[ \t]{{1,3}}"
        rf"(?:also[ \t]{{1,3}}|then[ \t]{{1,3}}|just[ \t]{{1,3}}|go[ \t]ahead[ \t]and[ \t]{{1,3}})?{_VERB}\b"
    ),
    # asking leave: "Should I delete", "OK to drop", "safe to remove", "want me to retire"
    re.compile(
        rf"(?i)\b(?:(?:should|shall|may|can|could)[ \t]{{1,3}}(?:I|we)|(?:do[ \t]you[ \t])?want[ \t]me[ \t]to"
        rf"|ok(?:ay)?[ \t]{{1,3}}to|safe[ \t]{{1,3}}to|fine[ \t]{{1,3}}to|go[ \t]ahead[ \t]and)"
        rf"[ \t]{{1,3}}(?:just[ \t]{{1,3}})?{_VERB}\b"
    ),
    # ("or" is left out: "add or remove assets" names a feature; "...or delete it?" is caught below)
    re.compile(
        rf"(?i)\b(?:yes|ok(?:ay)?|then|and|but|also|just|only)[,]?[ \t]{{1,3}}{_VERB}\b"
    ),
    re.compile(rf"(?i)\b{_VERB}[ \t]{{1,3}}(?:the[ \t]{{1,3}})?{_PRONOUN}\b"),
    re.compile(rf"(?i)\bby[ \t]{{1,3}}{_GERUND}\b"),
    # passive: "should be deleted", "can be removed", "to be dropped"
    re.compile(rf"(?i)\bbe[ \t]{{1,3}}{_PARTICIPLE}\b"),
    re.compile(
        rf"(?i)\b(?:confirm|approve)[ \t]{{1,3}}(?:the[ \t]{{1,3}})?(?:{_NOUN}|clean-?up)s?\b"
        rf"|\b(?:recommend|propose|proposing|suggest)[ \t]{{1,3}}(?:the[ \t]{{1,3}})?(?:{_GERUND}|{_NOUN})\b"
        r"|\b(?:can|could|should|shall|may)[ \t]{1,3}(?:it|they|these|those|this|that|[^\s?]{1,120})[ \t]{1,3}go(?=[ \t]{0,3}(?:\?|away\b))"
        r"|\blet[ \t]{1,3}(?:it|them)[ \t]{1,3}go\b|\bgone\?"
        r"|\bcomment[ \t]{1,3}(?:it|them|[^\s?]{1,120})[ \t]{1,3}out\b"
    ),
    # "fold/merge/consolidate X into Y": X stops existing
    # Only when a code-shaped thing is folded (`x()`, a ticked name, snake_case) or "it/them": folding
    # a doc section "into the standard" or a fix "into 0.9.1" removes nothing.
    re.compile(
        r"(?i)\b(?:fold|merge|consolidate|collapse)[ \t]{1,3}(?:it|them|these|those|\S{0,80}(?:\(\)|`|_)\S{0,80})"
        r"[ \t]{1,3}(?:[^\n.?!]{0,80}[ \t])?into\b"
    ),
    # a shell removal named in prose: "rm app/x.py", "git rm app/x.py"
    re.compile(
        r"(?i)(?:^|[\s`(])(?:git[ \t]{1,3})?rm[ \t]{1,3}(?:-[a-z]{1,4}[ \t]{1,3}){0,3}[\w./-]{1,200}"
    ),
    # the retroactive case: "keep it removed", "stays deleted", "keep as removed", "the deletion stands"
    re.compile(
        rf"(?i)\b(?:keep|leave)(?:[ \t]{{1,3}}[\w'()]{{1,40}}){{0,2}}[ \t]{{1,3}}(?:as[ \t]{{1,3}})?(?:{_PARTICIPLE}|gone)\b"
        rf"|\b(?:stays?|remains?)[ \t]{{1,3}}(?:{_PARTICIPLE}|gone)\b|\b{_NOUN}s?[ \t]{{1,3}}stands?\b"
    ),
)
# "don't delete them", "without removing": the verb is refused. "not only delete" is not a refusal.
_NEGATED = re.compile(
    r"(?i)(?:n't|\bnot(?![ \t]{1,3}only)|\bnever|\bwithout|\bno[ \t]need[ \t]to)[ \t]{1,3}(?:\w{1,20}[ \t]{1,3})?$"
    # someone else does it: "after you delete them", "when users remove one" describes, not proposes
    r"|\b(?:you|they|users?|customers?|he|she)[ \t]{1,3}$"
)
# "delete nothing", "delete no old guard": the object is none ("nothing else but X" is not).
_NOTHING = re.compile(r"[ \t]{1,3}(?:nothing(?![ \t]{1,3}else)|none|no)\b", re.I)
_MARKDOWN = re.compile(
    r"\*{1,3}|~~|^[ \t]{0,8}(?:[-*+>]|\d{1,3}[.)]|#{1,6})[ \t]{1,4}", re.M
)
_INVISIBLE = re.compile("[​‌‍⁠﻿­]")
_SPACES = re.compile(r"[ \t]{2,}")
_UNICODE_SPACE = re.compile("[\u00a0\u1680\u2000-\u200a\u202f\u205f\u3000]")
_FENCE = re.compile(r"```[^\n]{0,80}\n.{0,65536}?```", re.S)


def normalize(text: str) -> str:
    """Markdown, invisible characters, curly apostrophes and space runs out of the way."""
    text = _INVISIBLE.sub("", text[:_MAX_TEXT]).replace("’", "'")
    text = _UNICODE_SPACE.sub(" ", text)
    return _SPACES.sub(" ", _MARKDOWN.sub("", text))


# Where a removal word could be. The proposal patterns run only on windows around these, merged so
# no character is scanned twice: a 256 KB message costs one pass, not one pass per pattern.
_HINT = re.compile(
    r"delet|remov|drop|retir|prun|purg|nuk|wipe|excis|strip|rip|rid\b|clean|\bgo\b|gone|kill|trash"
    r"|scrap|toss|ditch|elimin|eras|\bbin|\bax|chop|sunset|fold|merge|consolid|collaps|\brm\b|comment"
)
_WINDOW = 200


def _windows(text: str) -> list[str]:
    spans: list[list[int]] = []
    # matched on a lowercased copy: case-folding in the regex engine was most of the hook's time
    for m in _HINT.finditer(text.lower()):
        lo = max(0, m.start() - _WINDOW)
        nl = text.rfind("\n", lo, m.start())
        lo = nl + 1 if nl >= 0 else lo
        hi = min(len(text), m.end() + _WINDOW)
        if spans and lo <= spans[-1][1]:
            spans[-1][1] = (
                hi  # overlapping: extend, so a hint near the edge keeps its context
            )
        else:
            spans.append([lo, hi])
    # a window cut mid-line must not look like a line start to the `^` patterns
    return [
        ("" if lo == 0 or text[lo - 1] == "\n" else "\x00 ") + text[lo:hi]
        for lo, hi in spans
    ]


def proposes_removal(text: str) -> bool:
    """Does this (normalized) text propose removing something? A refused verb does not count."""
    for win in _windows(text):
        for rx in _PROPOSAL:
            for m in rx.finditer(win):
                # "not only delete X" proposes it; the match then starts at "only"
                only = m.group(0)[:4].lower() == "only"
                refused = not only and _NEGATED.search(
                    win[max(0, m.start() - 32) : m.start()]
                )
                if not refused and not _NOTHING.match(win, m.end()):
                    return True
    return False


# ── The checkout: what can be proven ────────────────────────────────────────────────────────────
_IDENT = re.compile(r"[A-Za-z_][A-Za-z0-9_]{0,80}")
_PUNCT = "`'\"()[]{}<>,;"


def _code_shaped(word: str) -> bool:
    """A word that reads as an identifier, not English: an underscore, a digit, or internal capitals."""
    return (
        "_" in word
        or any(ch.isdigit() for ch in word)
        or any(ch.isupper() for ch in word[1:])
    )


class Repo:
    """What the checkout can prove: tracked paths, defined symbols, word counts and file contents.
    Every lookup is bounded in time and size; `readable` is False when nothing can be proven."""

    def __init__(self, root: Path | None) -> None:
        self.root = root.resolve() if root is not None else Path("/nonexistent")
        self._given = root is not None
        self._ready: bool | None = None
        self._suffixes: set[str] = set()
        self._defs: set[str] | None = None

    @property
    def readable(self) -> bool:
        """Is this a checkout git can read? Asked once, and only when a proposal needs it."""
        if self._ready is None:
            self._ready = (
                self._given
                and self.root.is_dir()
                and self._git("rev-parse", "--git-dir") is not None
            )
            if self._ready:
                self._index()
        return self._ready

    def _index(self) -> None:
        out = self._git("ls-files", "-z") or ""
        # every trailing part of every tracked file, and every leading directory, computed once:
        # `crud/base.py`, `app/crud/base.py` and `app/crud` all match in O(1)
        if out:
            for f in out.split("\0"):
                parts = [p for p in f.split("/") if p]
                for i in range(len(parts)):
                    self._suffixes.add("/".join(parts[i:]))
                    self._suffixes.add("/".join(parts[: i + 1]))

    def _git(self, *args: str, stdin: str = "") -> str | None:
        try:
            r = subprocess.run(
                ["git", "-C", str(self.root), *args],
                input=stdin.encode() if stdin else None,
                capture_output=True,
                timeout=3,
                check=False,
            )
        except _GIT_ERRORS:
            return None
        if r.returncode not in (0, 1):
            return None
        return r.stdout[:33554432].decode("utf-8", errors="replace")

    def is_tracked(self, name: str) -> bool:
        if not self.readable:
            return False
        name = (
            re.sub(r":\d{1,7}$", "", name.strip(_PUNCT + ".:"))
            .removeprefix("./")
            .rstrip("/")
        )
        return bool(name) and name in self._suffixes

    def defines(self, names: list[str]) -> set[str]:
        """Which of `names` are a `def`/`class` in a tracked file. ONE `git grep` lists every definition
        in the checkout, once per hook run, so the cost does not grow with the number of names (a
        pattern per name made 1800 names take 2 s)."""
        if self._defs is None:
            out = (
                self._git(
                    "grep",
                    "-h",
                    "-o",
                    "-I",
                    "-E",
                    r"^[[:space:]]*(async[[:space:]]+)?(def|class)[[:space:]]+[A-Za-z_][A-Za-z0-9_]*",
                    "--",
                    ".",
                )
                if self.readable
                else None
            )
            self._defs = set(re.findall(r"(?:def|class)\s+(\w+)", out or ""))
        return {n for n in names if n in self._defs}

    def count_words(self, symbol: str) -> int | None:
        """Lines in tracked files that contain `symbol` as a whole word (`git grep -cw`)."""
        out = self._git("grep", "-c", "-w", "-I", "-F", "-e", symbol, "--", ".")
        if out is None:
            return None
        return sum(
            int(ln.rsplit(":", 1)[1])
            for ln in out.splitlines()
            if ln.rsplit(":", 1)[-1].isdigit()
        )

    def resolve(self, raw: str) -> tuple[str, list[str]] | None:
        """(path relative to the checkout, its lines), or None when outside it or not a file."""
        p = Path(raw) if raw.startswith("/") else self.root / raw
        try:
            p = p.resolve()
            rel = p.relative_to(self.root)
            if not p.is_file() or p.stat().st_size > 8388608:
                return None
            return str(rel), p.read_text(
                encoding="utf-8", errors="replace"
            ).splitlines()
        except _PATH_ERRORS:
            return None


# ── Candidates and their blocks ─────────────────────────────────────────────────────────────────
_CLASSES = ("superseded", "never-wired", "orphaned")
_FIELD = re.compile(
    r"(?im)^[ \t]{0,8}(what|class|refs|successor|live|missing caller|why no successor)[ \t]{0,3}:[ \t]{0,8}([^\n]{0,1000})$"
)
_PATH_LINE = re.compile(
    r"(?<![\w./-])((?:/|\./|\.\./)?(?:[\w.-]{1,120}/){0,30}[\w.-]{1,120}\.\w{1,8}):(\d{1,7})\b"
)
_NOT_CODE = re.compile(
    rf"(?i)^not-code:[ \t]{{0,3}}({'|'.join(KINDS)})\b[ \t]{{0,8}}(\S[^\n]{{0,300}})?$"
)
_WIRE_LABEL = re.compile(
    r"(?i)^[\W]{0,8}(?:wire|build|implement|hook[ \t]up|connect|finish|restore[ \t]and[ \t]wire)\b"
)
_SEARCH = re.compile(r"(?i)\b(?:grep|rg|ag|git[ \t]grep|search(?:ed)?)\b")
_DEF = re.compile(r"^[ \t]*(?:async[ \t]+)?(?:def|class)[ \t]+([A-Za-z_]\w{0,80})")
_PROSE_FILE = re.compile(r"(?i)\.(?:md|markdown|rst|txt|adoc)$")
_CLAIMED = re.compile(r"->[ \t]{0,3}(\d{1,9})")
_PATH_ONLY = re.compile(
    r"^((?:\./)?(?:[\w.-]{1,120}/){0,30}[\w.-]{1,120}\.\w{1,8})(?![\w.:/-])"
)


def _candidates(text: str) -> list[dict[str, str]]:
    out: list[dict[str, str]] = []
    for m in _FIELD.finditer(text):
        key, val = m.group(1).lower(), m.group(2).strip()
        if key == "what":
            out.append({"what": val})
        elif out:
            out[-1].setdefault(key, val)
    return out


def _class_of(c: dict[str, str]) -> str:
    val = c.get("class", "").lower().replace("never wired", "never-wired")
    named = [k for k in _CLASSES if k in val]
    return named[0] if len(named) == 1 else ""


class Cite:
    """A resolved path:line field, or a whole file (`whole`: a template, a stylesheet, a module,
    whose identity is its path; its symbol is the file's stem)."""

    def __init__(
        self, rel: str, line: int, lines: list[str], symbol: str, whole: bool = False
    ) -> None:
        self.rel, self.line, self.lines, self.symbol = rel, line, lines, symbol
        self.whole = whole

    def _def_node(self) -> ast.FunctionDef | ast.AsyncFunctionDef | None:
        """The parsed `def` this cite points at (a `.py` file), or None."""
        line, name = self.def_near(self.symbol)
        if not line or not self.rel.endswith(".py"):
            return None
        try:
            tree = ast.parse("\n".join(self.lines))
        except _PARSE_ERRORS:
            return None
        for n in ast.walk(tree):
            if (
                isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
                and n.lineno == line
            ):
                return n
        return None

    def route_name(self) -> str:
        """The `name=` a decorator of this cite's `def` gives its route ("" if none), read from the
        parsed decorators themselves: a handler is reached through its route's name, never by its
        symbol."""
        fn = self._def_node()
        for d in getattr(fn, "decorator_list", []):
            if isinstance(d, ast.Call):
                for k in d.keywords:
                    if (
                        k.arg == "name"
                        and isinstance(k.value, ast.Constant)
                        and isinstance(k.value.value, str)
                    ):
                        return k.value.value
        return ""

    def own_lines(self) -> tuple[int, int]:
        """The lines of this cite's own definition: its decorators through its signature."""
        fn = self._def_node()
        if fn is None:
            line = self.def_near(self.symbol)[0] or self.line
            return line, line
        first = min([d.lineno for d in getattr(fn, "decorator_list", [])] + [fn.lineno])
        body = getattr(fn, "body", [])
        last = body[0].lineno - 1 if body and body[0].lineno > fn.lineno else fn.lineno
        return first, last

    def at(self) -> tuple[str, int]:
        return (self.rel, self.line)

    def def_near(self, symbol: str = "") -> tuple[int, str]:
        """(line, name) of a `def`/`class` within _NEAR lines (naming `symbol` if given), else (0, '')."""
        lo, hi = max(1, self.line - _NEAR), min(len(self.lines), self.line + _NEAR)
        for n in sorted(range(lo, hi + 1), key=lambda k: abs(k - self.line)):
            d = _DEF.match(self.lines[n - 1])
            if d and (not symbol or d.group(1) == symbol):
                return n, d.group(1)
        return 0, ""


def _whole_file(checkout: Repo, val: str) -> Cite | None:
    """`what: app/templates/x.html` (no line), or `path:N  <stem>` naming the file by its stem when
    the stem is not on that line: a file whose identity is its path."""
    m = _PATH_ONLY.match(val)
    if m and checkout.is_tracked(m.group(1)):
        got = checkout.resolve(m.group(1))
        if got is not None:
            return Cite(got[0], 1, got[1], Path(got[0]).stem, whole=True)
    m = _PATH_LINE.search(val)
    if m:
        rest = val[m.end() : m.end() + 200].strip().split()
        ident = _IDENT.findall(rest[0]) if rest else []
        got = checkout.resolve(m.group(1))
        if got is not None and ident and ident[-1] == Path(got[0]).stem:
            line = int(m.group(2))
            near = got[1][max(0, line - 1 - _NEAR) : line + _NEAR]
            if not any(_word_in(ident[-1], ln) for ln in near):
                return Cite(got[0], 1, got[1], ident[-1], whole=True)
    return None


def _cite(checkout: Repo, field: str, val: str) -> tuple[list[str], Cite | None]:
    if field in ("what", "successor"):
        whole = _whole_file(checkout, val)
        if whole is not None:
            return [], whole
    m = _PATH_LINE.search(val)
    if not m:
        return [f"`{field}:` needs a path:line (or, for a whole file, its path)"], None
    got = checkout.resolve(m.group(1))
    if got is None:
        return [f"`{field}:` {m.group(1)} is not a file inside this checkout"], None
    rel, lines = got
    line = int(m.group(2))
    if line < 1 or line > len(lines):
        return [f"`{field}:` {rel} has {len(lines)} lines, not {line}"], None
    rest = val[m.end() : m.end() + 200].strip().split()
    ident = _IDENT.findall(rest[0]) if rest else []
    return [], Cite(rel, line, lines, ident[-1] if ident else "")


def _is_code_line(text: str) -> bool:
    s = text.strip()
    return bool(s) and not s.startswith(("#", "//", "/*", "*", "--", "<!--"))


def _code_of(cite: Cite) -> str:
    """The cited line as code: its comments dropped, and nothing at all for a docstring line. A `.py`
    file is read by its tokenizer and parser; markup and scripts lose their comment forms. Prose a
    hook cannot tell from code is the author's word; a comment or docstring naming a symbol is no use
    of it (attack pass, v3)."""
    line = cite.lines[cite.line - 1]
    if cite.rel.endswith(".py"):
        src = "\n".join(cite.lines) + "\n"
        try:
            tree = ast.parse(src)
            docs: set[int] = set()
            for n in ast.walk(tree):
                if (
                    isinstance(n, ast.Expr)
                    and isinstance(n.value, ast.Constant)
                    and isinstance(n.value.value, str)
                ):
                    docs.update(range(n.lineno, (n.end_lineno or n.lineno) + 1))
            if cite.line in docs:
                return ""
            parts = []
            for tok in tokenize.generate_tokens(io.StringIO(src).readline):
                if tok.start[0] <= cite.line <= tok.end[0] and tok.type not in (
                    tokenize.COMMENT,
                    tokenize.NL,
                    tokenize.NEWLINE,
                    tokenize.INDENT,
                    tokenize.DEDENT,
                ):
                    parts.append(tok.string)
            return " ".join(parts)
        except _READ_ERRORS:
            return line if _is_code_line(line) else ""
    if not _is_code_line(line):
        return ""
    line = re.sub(r"\{#.{0,2000}?#\}|<!--.{0,2000}?-->", " ", line)
    if cite.rel.endswith((".js", ".mjs", ".ts")):
        line = re.sub(r"(?<![:\\'\"])//.{0,2000}$", "", line)
    return line


def _path_tail(path: str, other: str) -> str:
    """The shortest trailing part of `path` (whole components) that is not also a trailing part of
    `other`: what tells this file from the other one in a reference (`new/card.html`)."""
    parts = path.split("/")
    others = other.split("/")
    for k in range(1, len(parts) + 1):
        tail = parts[-k:]
        if tail != others[-k:]:
            return "/".join(tail)
    return path


def _word_in(word: str, text: str) -> bool:
    return re.search(rf"(?<![\w]){re.escape(word)}(?![\w])", text) is not None


def _not_code_gaps(what: str, checkout: Repo) -> list[str]:
    nc = _NOT_CODE.match(what)
    if not nc or not nc.group(2):
        return [f"`what: not-code:` needs a kind ({', '.join(KINDS)}) and a name"]
    if nc.group(1).lower() == "behaviour":
        return []  # a feature's behaviour: its own code is named, and nothing is removed
    tokens = [t.strip(_PUNCT) for t in nc.group(2).split()]
    # a tracked prose file (`docs/OLD.md`) IS a doc; a tracked source file or directory is code
    prose = nc.group(1).lower() == "doc"
    tracked = [
        t
        for t in tokens
        if checkout.is_tracked(t) and not (prose and _PROSE_FILE.search(t))
    ]
    defined = sorted(
        checkout.defines(
            [i for t in tokens for i in _IDENT.findall(t) if _code_shaped(i)]
        )
    )
    code = tracked + defined
    if code:
        return [
            f"`{code[0]}` is in this repo, so it is code: give it the code block, not `not-code:`"
        ]
    return []


def _superseded_gaps(c: dict[str, str], w: Cite | None, checkout: Repo) -> list[str]:
    gaps, s = _cite(checkout, "successor", c.get("successor", ""))
    succ_sym = route = ""
    if s and w and s.whole:
        # a file replaced by a file: another tracked file, named by the live line
        if s.rel == w.rel:
            gaps.append("`successor:` is the candidate itself")
        else:
            succ_sym = s.symbol
    elif s and w:
        s_line, succ_sym = s.def_near(s.symbol)
        w_line = w.def_near(w.symbol)[0] or w.line
        if (not w.whole and s.at() == w.at()) or (
            s.rel == w.rel and (w.whole or s_line == w_line)
        ):
            gaps.append("`successor:` is the candidate itself")
            succ_sym = ""
        elif not s_line:
            gaps.append(
                f"`successor:` {s.rel}:{s.line} is not at the `def`/`class` of a symbol"
            )
        else:
            route = s.route_name()
    g, live = _cite(checkout, "live", c.get("live", ""))
    gaps += g
    if live and w and (live.at() == w.at() or (w.whole and live.rel == w.rel)):
        gaps.append("`live:` is the candidate itself")
        return gaps
    if live and s and not s.whole and live.rel == s.rel:
        lo, hi = s.own_lines()
        if lo <= live.line <= hi:
            gaps.append(
                f"`live:` {live.rel}:{live.line} is the successor's own definition, not a use of it"
            )
            return gaps
    if live and succ_sym:
        text = _code_of(live)
        if s and w and s.whole:
            # a file named where it is used: by the part of its path that is not the candidate's, and
            # never on a line that still names the candidate (`old/card.html` beside `new/card.html`)
            mine = _path_tail(s.rel, w.rel)
            theirs = _path_tail(w.rel, s.rel)
            stems_collide = Path(s.rel).stem == Path(w.rel).stem
            named = mine in text or (not stems_collide and _word_in(succ_sym, text))
            if theirs in text:
                gaps.append(
                    f"`live:` {live.rel}:{live.line} still names the candidate ({theirs})"
                )
            elif not named:
                gaps.append(
                    f"`live:` {live.rel}:{live.line} is not code that uses {mine}"
                )
            return gaps
        # a route handler is used through its route's name (`url_path_for("docs.feedback.buttons")`)
        by_route = bool(route) and any(f"{q}{route}{q}" in text for q in "\"'")
        if not text or not (_word_in(succ_sym, text) or by_route):
            via = f" or its route `{route}`" if route else ""
            gaps.append(
                f"`live:` {live.rel}:{live.line} is not code that uses {succ_sym}{via}"
            )
    return gaps


def _gaps(c: dict[str, str], checkout: Repo) -> list[str]:
    what = c.get("what", "")
    if what.lower().startswith("not-code"):
        return _not_code_gaps(what, checkout)
    gaps, w = _cite(checkout, "what", what)
    sym = w.symbol if w else ""
    if w and not w.whole:
        near = w.lines[max(0, w.line - 1 - _NEAR) : w.line + _NEAR]
        if not sym:
            gaps.append(f"`what:` needs the symbol after {w.rel}:{w.line}")
        elif not any(_word_in(sym, ln) for ln in near):
            gaps.append(f"`what:` {sym} is not on or near {w.rel}:{w.line}")
            sym = ""
    klass = _class_of(c)
    if not klass:
        gaps.append(
            "`class:` must be exactly one of superseded | never-wired | orphaned"
        )
    refs = c.get("refs", "")
    claimed = _CLAIMED.search(refs)
    if not (_SEARCH.search(refs) and claimed):
        gaps.append("`refs:` needs the search you ran and its count, as `-> N`")
    elif sym:
        actual = checkout.count_words(sym)
        if actual is not None and actual != int(claimed.group(1)):
            gaps.append(
                f"`refs:` claims {claimed.group(1)}, but `git grep -cw {sym}` finds {actual}"
            )
    if "lanes" not in refs.lower():
        gaps.append("`refs:` needs `lanes:` (the dynamic lanes checked)")
    if klass == "superseded":
        gaps += _superseded_gaps(c, w, checkout)
    elif klass == "never-wired" and not c.get("missing caller"):
        gaps.append("never-wired needs `missing caller:` (what should call it)")
    elif klass == "orphaned" and not _SEARCH.search(c.get("why no successor", "")):
        gaps.append(
            "orphaned needs `why no successor:` naming the domain-noun search you ran"
        )
    return gaps


# Code-shaped names are found from a literal anchor and read backwards, so prose costs one pass.
_CALL = re.compile(r"\(\)")
_SOURCE = re.compile(r"\.(?:py|html|jinja2?|js|ts|css|sql|swift|sh|mk)\b")
_TICKED = re.compile(r"`([A-Za-z_][\w./-]{0,200})`")
# a code-shaped word (an underscore, a digit, or a capital after a lowercase letter), found by the
# regex itself: filtering every English word in Python was most of the time on a 256 KB message
_WORD = re.compile(
    r"(?<![A-Za-z0-9_])[A-Za-z_][A-Za-z0-9]{0,80}?(?:_|[0-9]|(?<=[a-z0-9])[A-Z])[A-Za-z0-9_]{0,80}(?![A-Za-z0-9_])"
)
_IDENT_CHARS = frozenset(
    "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_"
)
_PATH_CHARS = _IDENT_CHARS | frozenset("./-")


def _back(text: str, end: int, chars: frozenset[str], limit: int) -> int:
    i = end
    while i > 0 and end - i < limit and text[i - 1] in chars:
        i -= 1
    return i


def _names(text: str) -> list[str]:
    """Calls `name()`, source paths, `ticked` words, `Class.method`, and bare code-shaped words."""
    found: list[tuple[int, str]] = []
    for m in _CALL.finditer(text):
        i = _back(text, m.start(), _IDENT_CHARS | frozenset("."), 160)
        if i < m.start():
            found.append((i, text[i : m.end()].lstrip(".")))
    for m in _SOURCE.finditer(text):
        i = _back(text, m.start(), _PATH_CHARS, 400)
        if i < m.start():
            found.append((i, text[i : m.end()].strip("./")))
    for m in _TICKED.finditer(text):
        found.append((m.start(), m.group(1)))
    i = text.find(".")
    while 0 < i < len(text) - 1:
        if text[i - 1] in _IDENT_CHARS and text[i + 1].isalpha():
            lo = _back(text, i, _IDENT_CHARS, 80)
            hi = i + 1
            while hi < len(text) and hi - i < 80 and text[hi] in _IDENT_CHARS:
                hi += 1
            if text[lo].isupper():
                found.append((lo, text[lo:hi]))
        i = text.find(".", i + 1)
    found += [(m.start(), m.group(0)) for m in _WORD.finditer(text)]
    out: list[str] = []
    seen: set[str] = set()
    starts: set[int] = set()
    # a call and its bare word start at the same place: keep the first (the longer, call form)
    for at, tok in sorted(found, key=lambda f: (f[0], -len(f[1]))):
        if tok and at not in starts and tok not in seen:
            out.append(tok)
            seen.add(tok)
        starts.add(at)
    return out


def _last_ident(name: str) -> str:
    idents = _IDENT.findall(name.removesuffix("()"))
    return idents[-1] if idents else ""


def _is_path(name: str) -> bool:
    return "/" in name or _SOURCE.search(name) is not None


def _key(name: str) -> str:
    return name.strip("./") if _is_path(name) else (_last_ident(name) or name)


def _named_code(text: str, checkout: Repo) -> list[str]:
    """Names in `text` that are a tracked source file or a repo-defined symbol, in order."""
    raw = _names(text)
    defined = checkout.defines([_last_ident(t) for t in raw])  # one batched lookup
    out = []
    for t in raw:
        is_path = "/" in t or _SOURCE.search(t)
        if (is_path and checkout.is_tracked(t)) or (
            not is_path and _last_ident(t) in defined
        ):
            out.append(t)
    return out


# a sentence ends at `.`, `?` or `!` followed by space: a path's dots (`app/x.py`) do not end one
_SENTENCE = re.compile(r"(?<=[.?!])\s+")


def _paired(text: str, name: str) -> bool:
    """`name` sits in a sentence that proposes a removal (the same test the hook triggers on). With
    a behaviour block, only a name that is in no such sentence goes without its own block: a
    feature's code is named in a sentence of its own, never beside a removal. Fails closed: the
    owner reads "delete X" however it is phrased, and so does this."""
    key = _key(name)
    return any(
        _word_in(key, sentence) and proposes_removal(sentence)
        for sentence in _SENTENCE.split(text)
    )


def judge(text: str, labels: list[str], checkout: Repo) -> list[str]:
    """Problems with a removal proposal; [] when every candidate carries a block that checks out."""
    text = normalize(text)
    cands = _candidates(text)
    covered = "\n".join(
        c.get(k, "") for c in cands for k in ("what", "successor", "live")
    )
    # covered = the name (a path whole, a symbol by its last identifier) is a word in a block's
    # what/successor/live line; a name that only sits in prose or in `refs:` still needs a block
    unblocked = [
        n for n in _named_code(text, checkout) if not _word_in(_key(n), covered)
    ]
    if any(
        (nc := _NOT_CODE.match(c.get("what", "")))
        and nc.group(1).lower() == "behaviour"
        for c in cands
    ):
        # a question about a feature's behaviour names its code without proposing to remove it; a
        # name it makes the object of a removal is still a candidate and needs its block
        unblocked = [n for n in unblocked if _paired(text, n)]
    problems: list[str] = []
    if not cands:
        problems.append(
            "no candidate carries a block: each one needs its own `what:` block, or "
            "`what: not-code: <kind> <name>` when it is not repo code"
        )
    for c in cands:
        problems += [
            f"{c.get('what') or '(empty what:)'}: {g}" for g in _gaps(c, checkout)
        ]
    if unblocked:
        problems.append(
            f"named in this question with no block of its own: {', '.join(unblocked)}"
        )
    classes = {k for k in (_class_of(c) for c in cands) if k}
    if len(classes) > 1:
        problems.append(
            f"one question mixes {', '.join(sorted(classes))}: ask one question per class"
        )
    if "never-wired" in classes and not any(
        _WIRE_LABEL.search(normalize(lb)) for lb in labels
    ):
        problems.append(
            "a never-wired candidate needs an option whose label starts with Wire/Build/Implement: its "
            "question is WIRE it or DROP THE FEATURE, never an item in a delete batch"
        )
    return problems


def _deny(problems: list[str], where: str, reminder: bool = False) -> int:
    lines = "\n".join(f"  - {p}" for p in problems)
    head = (
        f"REMINDER (best effort, once): {where} asks to delete repo code without a block per candidate."
        if reminder
        else f"DENIED: {where} proposes a removal without a checkable block per candidate."
    )
    print(
        f"{head}\n{lines}\n"
        'Zero references answers "is this called?", not "should this exist?" '
        "(FLEET-AGENT-CONDUCT-STANDARD #6, `luxarch --playbook dead-code`). Repo code: classify each "
        "candidate as superseded, never-wired or orphaned, one question per class, with evidence that "
        f"exists in this checkout:\n\n{TEMPLATE}\n\nNot repo code ({', '.join(KINDS)}): one line is "
        f"enough, e.g. `{NOT_CODE}`.\nAsk removal questions with AskUserQuestion: that is the route "
        "this hook checks.\n",
        file=sys.stderr,
    )
    return 2


# ── The two routes ──────────────────────────────────────────────────────────────────────────────
def _question_texts(tool_input: dict[str, object]) -> list[tuple[str, list[str]]]:
    out: list[tuple[str, list[str]]] = []
    questions = tool_input.get("questions")
    if not isinstance(questions, list):
        return out
    for q in questions:
        if not isinstance(q, dict):
            continue
        labels: list[str] = []
        parts = [str(q.get("header") or ""), str(q.get("question") or "")]
        options = q.get("options")
        for o in options if isinstance(options, list) else []:
            if isinstance(o, dict):
                labels.append(str(o.get("label") or ""))
                parts += [str(o.get("label") or ""), str(o.get("description") or "")]
        out.append(("\n".join(parts)[:_MAX_TEXT], labels))
    return out


def _text_of(content: object) -> str:
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return "\n".join(
            str(b.get("text") or "")
            for b in content
            if isinstance(b, dict) and b.get("type") == "text"
        )
    return ""


def final_message(ev: dict[str, object]) -> str:
    """The final assistant message, or '' when the transcript's final entry is not one with text.
    Earlier turns are never judged."""
    given = ev.get("last_assistant_message")
    if isinstance(given, str):
        return given
    path = ev.get("transcript_path")
    if not isinstance(path, str) or not path:
        return ""
    try:
        with open(path, "rb") as fh:
            fh.seek(0, os.SEEK_END)
            size = fh.tell()
            fh.seek(max(0, size - 1048576))
            tail = fh.read().decode("utf-8", errors="replace")
    except OSError:
        return ""
    for line in reversed(tail.splitlines()):
        try:
            entry = json.loads(line)
        except ValueError:
            continue
        if not isinstance(entry, dict) or entry.get("type") not in (
            "user",
            "assistant",
        ):
            continue
        if entry.get("type") != "assistant":
            return ""
        msg = entry.get("message")
        return _text_of(msg.get("content") if isinstance(msg, dict) else None)
    return ""


def stop_reminder(text: str, checkout: Repo) -> list[str]:
    """Problems for a final message whose last paragraph asks to remove repo code; else []."""
    tail = normalize(_FENCE.sub("", text[-_STOP_TAIL:])).rstrip()
    paras = [p for p in re.split(r"\n[ \t]{0,8}\n", tail) if p.strip()]
    if not paras or "?" not in paras[-1] or not proposes_removal(paras[-1]):
        return []
    if not checkout.readable:
        return []
    # Blocks are read with fences kept: the playbook shows the format in a ```text fence, and agents
    # copy it that way. Stripped, a correct block vanished and every file the prose named (one the
    # change only ADDED to) was reported as a candidate with no block.
    cands = _candidates(normalize(text[-_STOP_TAIL:]))
    if cands:
        # a block silences the reminder only if it passes the same checks as on AskUserQuestion
        return [f"{c.get('what')}: {g}" for c in cands for g in _gaps(c, checkout)]
    named = _named_code(paras[-1], checkout) or _named_code(
        "\n".join(paras[-2:]), checkout
    )
    return [f"named with no block: {', '.join(named)}"] if named else []


def _git_out(root: Path, *args: str) -> str | None:
    try:
        r = subprocess.run(
            ["git", "-C", str(root), *args],
            capture_output=True,
            text=True,
            timeout=5,
            check=False,
        )
    except _GIT_ERRORS:
        return None
    return r.stdout.strip() if r.returncode == 0 and r.stdout.strip() else None


def _session_checkout(project: str | None, cwd: object) -> Path | None:
    """The checkout the session is working in. Every agent works in its issue's worktree
    (`.claude/worktrees/<KEY>`) and the main checkout stays on the base branch, so a successor the
    agent just wrote exists only in the worktree: judging the main checkout denied every correct
    "superseded" proposal. The event's cwd is used when it is a working tree of the SAME repository
    as $CLAUDE_PROJECT_DIR (one git common directory); anything else is not trusted, and the project
    checkout is judged as before."""
    if not project:
        return None
    base = Path(project)
    if not isinstance(cwd, str) or not cwd:
        return base
    here = Path(cwd)
    if not here.is_dir():
        return base
    top = _git_out(here, "rev-parse", "--show-toplevel")
    mine = _git_out(here, "rev-parse", "--path-format=absolute", "--git-common-dir")
    theirs = _git_out(base, "rev-parse", "--path-format=absolute", "--git-common-dir")
    if top and mine and theirs and Path(mine).resolve() == Path(theirs).resolve():
        return Path(top)
    return base


def main() -> int:
    try:
        ev = json.load(sys.stdin)
    except Exception:
        return 0
    if not isinstance(ev, dict):
        return 0
    project = os.environ.get("CLAUDE_PROJECT_DIR")
    checkout = Repo(_session_checkout(project, ev.get("cwd")))
    # An unreadable checkout (CLAUDE_PROJECT_DIR unset, missing, not git) proves nothing, so nothing
    # is refused: the whole question passes, on both routes alike. Checked only once a proposal needs it.
    if ev.get("tool_name") == ASK_TOOL:
        ti = ev.get("tool_input")
        for n, (text, labels) in enumerate(
            _question_texts(ti if isinstance(ti, dict) else {}), 1
        ):
            if proposes_removal(normalize(text)):
                if not checkout.readable:
                    return 0
                problems = judge(text, labels, checkout)
                if problems:
                    return _deny(problems, f"question {n}")
        return 0
    if ev.get("hook_event_name") == "Stop" and not ev.get("stop_hook_active"):
        text = final_message(ev)
        problems = stop_reminder(text, checkout) if text else []
        if problems:
            return _deny(problems, "your last message", reminder=True)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception:
        sys.exit(0)
